/// <summary>
/// MPJ_11539 - kscerri - 27/07/2021
/// Class <c>METPrintMgmtReportFormatPopulatorAppSuite_Extension</c> populates the PrintMgmtReportFormat table used for print management 
/// with the documents.
/// </summary>
[ExtensionOf(classStr(PrintMgmtReportFormatPopulator))]
public final class METPrintMgmtReportFormatPopulatorAppSuite_Extension
{
    #ISOCountryRegionCodes
    #PrintMgmtSetup


}

Method.Source:
    /// <summary>
    /// MPJ_11539 - kscerri - 27/07/2021
    /// adds documents
    /// </summary>
    protected void addDocuments()
    {
        this.customAddSalesDocuments();

        // Purchasing documents
        this.customAddPurchaseDocuments();

        // CB123 SalesOrderExtractScreenforCSD - start
        this.customAddinventDocuments();
        // CB123 SalesOrderExtractScreenforCSD - end

        //CB231 - Container content report
        this.customAddWarehouseDocuments();
        //CB231 - Container content report

        next addDocuments();
    }

    /// <summary>
    /// MPJ_11539 - kscerri - 27/07/2021
    /// Adds sales records to the PrintMgmtReportFormat table.
    /// </summary>
    private void customAddSalesDocuments()
    {
        //Use this method as we need the Fifth parameter "PrintMgmtReportFormatSystem" = True for Accountable documents that are configured in Print Management.
        //If its missing then we can get "Report name in report contract cannot be null or empty." errors on reprints. Also acts as setting a report as default 
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::METCustActivityStatement, ssrsReportStr(METCustActivityStatement, Report), ssrsReportStr(METCustActivityStatement, Report), #NoCountryRegionId, true);
        
        //MPJ_15231_Customer Statement DCP 17/05/2022
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::METCustActivityStatementMulti, ssrsReportStr(METCustActivityStatement, ReportMulti), ssrsReportStr(METCustActivityStatement, ReportMulti), #NoCountryRegionId, true);

        //CB175 - Sales Confirmation - start
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::SalesOrderConfirmation, ssrsReportStr(METSalesConfirm, ReportLiquor), ssrsReportStr(METSalesConfirm, ReportLiquor), #NoCountryRegionId, true);

        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::SalesOrderConfirmation, ssrsReportStr(METSalesConfirm, ReportFood), ssrsReportStr(METSalesConfirm, ReportFood), #NoCountryRegionId, true);
        //CB175 - Sales Confirmation - end
        
    }

    ///
    /// Adds purchase records to the PrintMgmtReportFormat table.
    ///
    protected void customAddPurchaseDocuments()
    {
        this.addOther(PrintMgmtDocumentType::METArrivalOverviewDockCopy, ssrsReportStr(METArrivalDockCopy, Report), ssrsReportStr(METArrivalDockCopy, Report), #NoCountryRegionId);

        //CB714 - POConfirmationReports - start
        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderRequisition, ssrsReportStr(METPurchPurchaseOrder, ReportImport), ssrsReportStr(METPurchPurchaseOrder, ReportImport), #NoCountryRegionId, true);

        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderRequisition, ssrsReportStr(METPurchPurchaseOrder, ReportTrade), ssrsReportStr(METPurchPurchaseOrder, ReportTrade), #NoCountryRegionId, true);

        PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::PurchaseOrderRequisition, ssrsReportStr(METPurchPurchaseOrder, ReportReturn), ssrsReportStr(METPurchPurchaseOrder, ReportReturn), #NoCountryRegionId, true);
        //CB714 - POConfirmationReports - end
    }

/// <summary>
/// CB123 SalesOrderExtractScreenforCSD
/// Adds sales records to the PrintMgmtReportFormat table.
/// </summary>
private void customAddInventDocuments()
{
    PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::InventPickList, ssrsReportStr(METWMSPickingList_OrderPick, Report), ssrsReportStr(METWMSPickingList_OrderPick, Report), #NoCountryRegionId, true);
}

/// <summary>
/// CB231 - Container content report
/// Adds sales records to the PrintMgmtReportFormat table.
/// </summary>
private void customAddWarehouseDocuments()
{
    PrintMgmtDelegatesHandler::add(PrintMgmtDocumentType::METContainerContentReport, ssrsReportStr(METCCRReport, Report), ssrsReportStr(METCCRReport, Report), #NoCountryRegionId, true);
}
